capstones.solution:
let temp = signal(300)
let fan = GPIO::new(5)
let log = []
when temp.get() > 330 for 1[s] { fan.set_high(); log.push("fan on") } else { fan.set_low(); log.push("fan off") }
always temp.get() < 360 else { log.push("SHUTDOWN") }
temp.set(335); sleep(0.5)
temp.set(320)
temp.set(340); sleep(1.5)
temp.set(365)
temp.set(310); sleep(0.1)
print(fan.read(), log)
